(7439674, 1176434, 50641, '<td valign="top">oh gyaban</td>', 'oh gyaban', '2016-02-26 00:07:24.000000', NULL, 1),
(7439675, 1176510, 50641, '<td valign="top">Mama I hate that story, read me another</td>', 'Mama I hate that story, read me another', '2016-02-26 00:08:18.000000', NULL, 1),
(7439721, 1176521, 181814, '<td valign="top">What I think was supposed to be the white background, is not white at all and the dirt splattered all over it is very distracting. I don''t think I can consider the bright red subject as a lighter color so I don''t think this is on theme at all.</td>', 'What I think was supposed to be the white background, is not white at all and the dirt splattered all over it is very distracting. I don''t think I can consider the bright red subject as a lighter color so I don''t think this is on theme at all.', '2016-02-26 09:24:49.000000', NULL, 1),
(7439722, 1176389, 181814, '<td valign="top">I would like to see better focus on the subject, there are also a lot of dust particles throughout the photograph that takes away from the overall appearance.</td>', 'I would like to see better focus on the subject, there are also a lot of dust particles throughout the photograph that takes away from the overall appearance.', '2016-02-26 09:26:35.000000', NULL, 1),
(7439723, 1176375, 181814, '<td valign="top">It is not a bad photograph but it is not on theme at all.</td>', 'It is not a bad photograph but it is not on theme at all.', '2016-02-26 09:27:18.000000', NULL, 1),
(7439724, 1176524, 181814, '<td valign="top">The subject seems to be over exposed causing blown out highlights.</td>', 'The subject seems to be over exposed causing blown out highlights.', '2016-02-26 09:28:17.000000', NULL, 1),
(7439725, 1176350, 181814, '<td valign="top">I don''t see a white background so I will consider this off theme.</td>', 'I don''t see a white background so I will consider this off theme.', '2016-02-26 09:29:01.000000', NULL, 1),
(7439726, 1176355, 181814, '<td valign="top">The entire photograph is more yellow in color than anything else, it definitely doesn''t have a white background.</td>', 'The entire photograph is more yellow in color than anything else, it definitely doesn''t have a white background.', '2016-02-26 09:30:33.000000', NULL, 1),
(7439728, 1176293, 181814, '<td valign="top">The white balance is off and it is a bit under exposed creating a blueish tone to the white areas and the is a lot of noise in the photograph.</td>', 'The white balance is off and it is a bit under exposed creating a blueish tone to the white areas and the is a lot of noise in the photograph.', '2016-02-26 09:34:06.000000', NULL, 1),
